namespace Autonogrammer.Harness.Automations.Hosted;

/// <summary>
/// The result of creating, replacing or changing an automation through <see cref="AutomationService"/>. It holds a webhook secret only
/// when one was generated by that call: the secret is shown once and cannot be read again. It is a class without a text form so a log
/// line that prints it cannot leak the secret.
/// </summary>
public sealed class AutomationChange
{
    private AutomationChange(UserAutomation? automation, string? webhookSecret, IReadOnlyList<AutomationValidationIssue> issues, bool notFound)
    {
        Automation = automation;
        WebhookSecret = webhookSecret;
        Issues = issues;
        NotFound = notFound;
    }

    /// <summary>Gets the automation after the change, or null when the change was refused.</summary>
    public UserAutomation? Automation { get; }

    /// <summary>Gets the webhook secret generated by the call, or null when none was generated.</summary>
    public string? WebhookSecret { get; }

    /// <summary>Gets the reasons the change was refused as invalid; empty when it succeeded or the automation was not found.</summary>
    public IReadOnlyList<AutomationValidationIssue> Issues { get; }

    /// <summary>Gets whether the automation does not exist or belongs to another owner. Both read the same.</summary>
    public bool NotFound { get; }

    /// <summary>Gets whether the change was applied.</summary>
    public bool Succeeded => Automation is not null;

    /// <summary>Creates the result of an applied change.</summary>
    /// <param name="automation">The automation.</param>
    /// <param name="webhookSecret">The generated secret, or null.</param>
    /// <returns>The result.</returns>
    public static AutomationChange Applied(UserAutomation automation, string? webhookSecret) => new(automation, webhookSecret, [], false);

    /// <summary>Creates the result of a change refused as invalid.</summary>
    /// <param name="issues">The reasons.</param>
    /// <returns>The result.</returns>
    public static AutomationChange Invalid(IReadOnlyList<AutomationValidationIssue> issues) => new(null, null, issues, false);

    /// <summary>Creates the result for an automation that is not there for this owner.</summary>
    /// <returns>The result.</returns>
    public static AutomationChange Missing() => new(null, null, [], true);
}
